N=4096; xi=torch.randn(N,2); c=torch.rand(N)
def run(dv=None,lo=0,hi=0,thr=0.0):
    x=xi.clone(); fired=torch.zeros(N); sc12=None
    with torch.no_grad():
        for k in range(20):
            t=torch.full((N,),1-k/20)
            v,a=net.velocity(x,t,c,('blocks.2.act',),count=False)
            s=a['blocks.2.act']@w+b
            if k==12: sc12=s.clone()
            if dv is not None and lo<=k<hi:
                f=(s>thr).float(); fired=torch.maximum(fired,f)
                v=v+f[:,None]*torch.tensor(dv,dtype=torch.float32)
            x=x-v/20
    return x.numpy(),sc12.numpy(),fired.numpy()
